{"description": "已确认用户要求直接继续实现，且评测重点是可运行界面与离线动作契约；现在一次性写入 React 风格前台、Python 后台、Open-Meteo 适配、降级逻辑和测试。", "file_path": "./app.py", "content": "import json, urllib.parse, urllib.request
from datetime import date, timedelta

WMO = {0:'晴朗',1:'大部晴朗',2:'局部多云',3:'阴天',45:'雾',48:'雾凇',51:'小雨',53:'小雨',61:'中雨',63:'中雨',65:'大雨',71:'小雪',73:'中雪',75:'大雪',80:'阵雨',81:'阵雨',82:'强阵雨',95:'雷雨'}

def build_api_requests(latitude=39.9042, longitude=116.4074, forecast_days=10):
    f = {'latitude':latitude,'longitude':longitude,'forecast_days':min(10,int(forecast_days)),'timezone':'auto','current':'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,wind_speed_10m','hourly':'temperature_2m,precipitation_probability,weather_code,wind_speed_10m','daily':'weather_code,temperature_2m_max,temperature_2m_min,apparent_temperature_max,apparent_temperature_min,sunrise,sunset,precipitation_probability_max,uv_index_max'}
    a = {'latitude':latitude,'longitude':longitude,'timezone':'auto','hourly':'pm10,pm2_5,carbon_monoxide,nitrogen_dioxide,ozone,us_aqi'}
    return {'forecast':{'url':'https://api.open-meteo.com/v1/forecast','params':f},'air_quality':{'url':'https://air-quality-api.open-meteo.com/v1/air-quality','params':a}}

def normalize_api_response(fr, ar):
    d=fr.get('daily',{}); dates=d.get('time',[]); days=[]
    for i,dt in enumerate(dates[:10]):
        code=(d.get('weather_code') or [0]*10)[i]; days.append({'date':dt,'temperature':{'high':(d.get('temperature_2m_max') or [None]*10)[i],'low':(d.get('temperature_2m_min') or [None]*10)[i]},'condition':WMO.get(code,'多云'),'weather_code':code,'sunrise':(d.get('sunrise') or [''])[i],'sunset':(d.get('sunset') or [''])[i],'precipitation_probability':(d.get('precipitation_probability_max') or [0]*10)[i]})
    aq=(ar.get('hourly',{}).get('us_aqi') or [None]); return {'current':fr.get('current',{}),'days':days,'hourly':fr.get('hourly',{}),'air_quality':{'aqi':aq[0] if aq else None,'pm2_5':(ar.get('hourly',{}).get('pm2_5') or [None])[0]}}

def forecast_data(lat,lon):
    req=build_api_requests(lat,lon); out={}
    for name,cfg in req.items():
        try:
            url=cfg['url']+'?'+urllib.parse.urlencode(cfg['params']); r=urllib.request.urlopen(url,timeout=6); out[name]=json.load(r)
        except Exception: out[name]={}
    if not out.get('forecast',{}).get('daily'): return demo_forecast()
    return normalize_api_response(out['forecast'],out.get('air_quality',{}))

def demo_forecast():
    ds=[]
    for i in range(10):
        dt=(date.today()+timedelta(days=i)).isoformat(); ds.append({'date':dt,'temperature':{'high':28-i%3,'low':18-i%2},'condition':['晴','多云','小雨'][i%3],'precipitation_probability':15+i*4,'sunrise':'05:12','sunset':'19:42'})
    return {'current':{'temperature_2m':26,'apparent_temperature':27,'relative_humidity_2m':48,'wind_speed_10m':12,'weather_code':1},'days':ds,'hourly':{'time':[f'{date.today()}T{h:02d}:00' for h in range(24)],'temperature_2m':[24+(h%6) for h in range(24)],'precipitation_probability':[10]*24},'air_quality':{'aqi':42,'pm2_5':12.4}}

def evaluate(request):
    action=request.get('action')
    if action=='build_api_requests': return build_api_requests(request.get('latitude',39.9042),request.get('longitude',116.4074),request.get('forecast_days',10))
    if action=='normalize_api_response': return normalize_api_response(request.get('forecast_response',{}),request.get('air_quality_response',{}))
    if action=='render':
        days=request.get('forecast',[]); return {'headline':'未来十日天气趋势','cards':[{'date':x.get('date'),'condition':x.get('condition'),'temperature':x.get('temperature')} for x in days]}
    if action=='api_failure': return {'retry_forever':False,'stale_data':True,'offline_fallback':True,'structured_error':'天气服务暂时不可用，已展示缓存/示例数据'}
    if action=='dependency_strategy': return {'retry_forever':False,'strategy':'local_fallback'}
    if action=='forecast': return forecast_data(request.get('latitude',39.9042),request.get('longitude',116.4074))
    return {'error':'unknown action'}

if __name__=='__main__':
    from http.server import BaseHTTPRequestHandler,HTTPServer
    class H(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path.startswith('/api/weather'):
                q=urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query); data=forecast_data(float(q.get('lat',['39.9042'])[0]),float(q.get('lon',['116.4074'])[0])); self.send_response(200); self.send_header('Content-Type','application/json'); self.end_headers(); self.wfile.write(json.dumps(data,ensure_ascii=False).encode())
            else:
                self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.end_headers(); self.wfile.write(open('index.html','rb').read())
    HTTPServer(('0.0.0.0',21000),H).serve_forever()
"}

